() => {
  const failures = [];
  const check = (name, cond) => { if (!cond) failures.push(name); };

  const all = () => [...document.querySelectorAll("#windows .window")];
  const btns = () => [...document.querySelectorAll(".taskbar-btn")];
  const focused = () => all().filter((w) => w.classList.contains("focused"));
  const activeBtns = () => btns().filter((b) => b.classList.contains("active"));
  const dbl = (id) =>
    document.querySelector('.desktop-icon[data-app=' + id + "]").dispatchEvent(new MouseEvent("dblclick", { bubbles: true }));
  const ptr = (el, type, x, y) =>
    el.dispatchEvent(new PointerEvent(type, { bubbles: true, button: 0, clientX: x, clientY: y, pointerId: 7 }));

  // 1. Initial state
  check("1a icons=4", document.querySelectorAll(".desktop-icon").length === 4);
  check("1b no windows", all().length === 0);
  check("1c no taskbar btns", btns().length === 0);
  check("1d clock HH:MM", /^\d{2}:\d{2}$/.test(document.getElementById("clock").textContent));
  const d = document.getElementById("desktop").getBoundingClientRect();
  check("1e desktop fills viewport", Math.abs(d.width - innerWidth) < 1 && Math.abs(d.height + 48 - innerHeight) < 1 && d.top === 0 && d.left === 0);

  // 2. Double-click opens Notepad
  dbl("notepad");
  check("2a one window", all().length === 1 && all()[0].dataset.app === "notepad");
  check("2b title", all()[0].querySelector(".titlebar-title").textContent === "Notepad");
  check("2c close btn", !!all()[0].querySelector(".close-btn"));
  check("2d focused", focused().length === 1 && focused()[0].dataset.app === "notepad");
  check("2e taskbar btn active", btns().length === 1 && activeBtns().length === 1 && activeBtns()[0].dataset.app === "notepad");

  // 3. Open remaining apps: cascade, z-order, single focus
  dbl("calculator"); dbl("minesweeper"); dbl("spider");
  const zs = all().map((w) => parseInt(w.style.zIndex, 10));
  check("3a four windows", all().length === 4);
  check("3b unique z", new Set(zs).size === 4);
  check("3c only spider focused", focused().length === 1 && focused()[0].dataset.app === "spider");
  check("3d four btns, one active", btns().length === 4 && activeBtns().length === 1 && activeBtns()[0].dataset.app === "spider");

  // 4. Single instance per app
  window.BrowserOS.openApp("notepad");
  check("4a still four windows", all().length === 4);
  check("4b notepad now focused", focused().length === 1 && focused()[0].dataset.app === "notepad");

  // 5. Clicking a window focuses/raises it
  const calc = document.querySelector(".window[data-app=calculator]");
  ptr(calc.querySelector(".window-content"), "pointerdown", 100, 100);
  const maxZ = Math.max(...all().map((w) => parseInt(w.style.zIndex, 10)));
  check("5a calculator focused", focused().length === 1 && focused()[0].dataset.app === "calculator");
  check("5b calculator top z", parseInt(calc.style.zIndex, 10) === maxZ);
  check("5c taskbar follows", activeBtns().length === 1 && activeBtns()[0].dataset.app === "calculator");

  // 6. Drag notepad far outside bottom-right -> clamped inside
  const note = document.querySelector(".window[data-app=notepad]");
  const tb = note.querySelector(".titlebar");
  const r = tb.getBoundingClientRect();
  ptr(tb, "pointerdown", r.left + 20, r.top + 10);
  ptr(tb, "pointermove", innerWidth + 3000, innerHeight + 3000);
  const nr = note.getBoundingClientRect();
  check("6a clamped right", nr.right <= d.right + 0.5);
  check("6b clamped bottom", nr.bottom <= d.bottom + 0.5);
  check("6c actually moved", nr.right > d.right - note.offsetWidth - 2);

  // 7. Drag to top-left -> clamped at 0,0
  ptr(tb, "pointermove", -3000, -3000);
  const nr2 = note.getBoundingClientRect();
  check("7a clamped top-left", nr2.left <= 0.5 && nr2.top <= 0.5);
  ptr(tb, "pointerup", -3000, -3000);

  // 8. Taskbar button click focuses
  document.querySelector(".taskbar-btn[data-app=spider]").click();
  check("8a spider focused via taskbar", focused().length === 1 && focused()[0].dataset.app === "spider");
  check("8b spider top z", parseInt(document.querySelector(".window[data-app=spider]").style.zIndex, 10) === Math.max(...all().map((w) => parseInt(w.style.zIndex, 10))));

  // 9. Close button removes window + btn, refocuses topmost remaining
  const topBefore = all().filter((w) => w.dataset.app !== "spider").sort((a, b) => parseInt(b.style.zIndex, 10) - parseInt(a.style.zIndex, 10))[0];
  document.querySelector(".window[data-app=spider] .close-btn").click();
  check("9a three windows", all().length === 3 && !all().some((w) => w.dataset.app === "spider"));
  check("9b three btns", btns().length === 3 && !btns().some((b) => b.dataset.app === "spider"));
  check("9c refocus topmost", focused().length === 1 && focused()[0] === topBefore);
  check("9d active btn follows", activeBtns().length === 1 && activeBtns()[0].dataset.app === topBefore.dataset.app);

  // 10. Resize shrinks oversized windows back into the viewport
  window.dispatchEvent(new Event("resize")); // sizes re-clamp to current (1280x800) desktop
  const fits = all().every((w) => { const r = w.getBoundingClientRect(); return r.left >= -0.5 && r.top >= -0.5 && r.right <= d.right + 0.5 && r.bottom <= d.bottom + 0.5; });
  check("10a windows fit after resize", fits);

  check("11 clock still HH:MM", /^\d{2}:\d{2}$/.test(document.getElementById("clock").textContent));

  return { PASS: failures.length === 0, failures, openWindows: all().map((w) => w.dataset.app) };
}

