/* ============================================================
   Browser OS — desktop shell (ticket 1)
   Flat, modern look: rounded corners, soft shadows,
   translucent blurred taskbar, system font stack.
   ============================================================ */

:root {
  --accent: #4a7dff;
  --accent-soft: rgba(74, 125, 255, 0.22);
  --window-bg: rgba(250, 251, 253, 0.94);
  --window-border: rgba(255, 255, 255, 0.55);
  --titlebar-bg: rgba(238, 242, 248, 0.92);
  --text: #1d2430;
  --text-soft: #5b6472;
  --shadow: 0 8px 24px rgba(15, 23, 42, 0.18);
  --shadow-focused: 0 18px 44px rgba(15, 23, 42, 0.34);
  --radius: 12px;
  --taskbar-height: 48px;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  height: 100%;
  overflow: hidden;
}

body {
  font-family: var(--font);
  color: var(--text);
  -webkit-font-smoothing: antialiased;
}

/* ---------- Desktop ---------- */

/* Fills the viewport above the taskbar.
   Placeholder wallpaper: ticket 2 adds switchable CSS presets. */
#desktop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: var(--taskbar-height);
  background: linear-gradient(135deg, #8ec5ff 0%, #6a8dff 55%, #9b6dff 100%);
  user-select: none;
  overflow: hidden;
}

/* ---------- Desktop icons ---------- */

#icons {
  position: absolute;
  top: 14px;
  left: 14px;
  display: flex;
  flex-direction: column;
  flex-wrap: wrap;
  gap: 6px;
  max-height: calc(100% - 28px);
}

.desktop-icon {
  width: 92px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 10px 4px;
  font-family: inherit;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 10px;
  cursor: pointer;
}

.desktop-icon:hover {
  background: rgba(255, 255, 255, 0.16);
}

.desktop-icon:focus-visible {
  outline: 2px solid #fff;
  outline-offset: -2px;
}

.desktop-icon.selected {
  background: rgba(255, 255, 255, 0.26);
  border-color: rgba(255, 255, 255, 0.45);
}

.icon-glyph {
  font-size: 40px;
  line-height: 1;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.25));
}

.icon-label {
  font-size: 12.5px;
  font-weight: 500;
  color: #fff;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.45);
  padding: 2px 6px;
  border-radius: 6px;
}

/* ---------- Windows ---------- */

#windows {
  position: absolute;
  inset: 0;
  overflow: hidden;
}

.window {
  position: absolute;
  display: flex;
  flex-direction: column;
  min-width: 240px;
  min-height: 150px;
  background: var(--window-bg);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid var(--window-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
}

/* Focused window: stronger shadow + highlighted title bar */
.window.focused {
  box-shadow: var(--shadow-focused);
}

.window.focused .titlebar {
  background: #fff;
  box-shadow: inset 0 -2px 0 var(--accent);
}

/* Title bar: app name + close button, drag handle */
.titlebar {
  height: 40px;
  flex: 0 0 40px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 8px 0 12px;
  background: var(--titlebar-bg);
  touch-action: none;
}

.window.dragging .titlebar {
  cursor: grabbing;
}

.titlebar-icon {
  font-size: 16px;
  line-height: 1;
}

.titlebar-title {
  flex: 1;
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.window:not(.focused) .titlebar-title {
  color: var(--text-soft);
}

.close-btn {
  width: 32px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--text-soft);
  font-size: 14px;
  line-height: 1;
  cursor: pointer;
}

.close-btn:hover {
  background: rgba(208, 62, 62, 0.14);
  color: #c0392b;
}

.close-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

/* Window body — placeholder content until app tickets land */
.window-content {
  flex: 1;
  min-height: 0;
  padding: 20px;
  overflow: auto;
}

.placeholder {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  text-align: center;
  color: var(--text-soft);
  font-size: 13.5px;
}

.placeholder .placeholder-glyph {
  font-size: 48px;
  line-height: 1;
}

/* ---------- Taskbar ---------- */

#taskbar {
  position: fixed;
