/* ============================================================
   Browser OS — desktop shell (ticket 1)
   Flat, modern look: rounded corners, soft shadows,
   translucent blurred taskbar, system font stack.
   ============================================================ */

:root {
  --accent: #4a7dff;
  --accent-soft: rgba(74, 125, 255, 0.22);
  --window-bg: rgba(250, 251, 253, 0.94);
  --window-border: rgba(255, 255, 255, 0.55);
  --titlebar-bg: rgba(238, 242, 248, 0.92);
  --text: #1d2430;
  --text-soft: #5b6472;
  --shadow: 0 8px 24px rgba(15, 23, 42, 0.18);
  --shadow-focused: 0 18px 44px rgba(15, 23, 42, 0.34);
  --radius: 12px;
  --taskbar-height: 48px;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  height: 100%;
  overflow: hidden;
}

body {
  font-family: var(--font);
  color: var(--text);
  -webkit-font-smoothing: antialiased;
}

/* ---------- Desktop ---------- */

/* Fills the viewport above the taskbar.
   Placeholder wallpaper: ticket 2 adds switchable CSS presets. */
#desktop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: var(--taskbar-height);
  background: linear-gradient(135deg, #8ec5ff 0%, #6a8dff 55%, #9b6dff 100%);
  user-select: none;
  overflow: hidden;
}

/* ---------- Desktop icons ---------- */

#icons {
  position: absolute;
  top: 14px;
  left: 14px;
  display: flex;
  flex-direction: column;
  flex-wrap: wrap;
  gap: 6px;
  max-height: calc(100% - 28px);
}

.desktop-icon {
  width: 92px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 10px 4px;
  font-family: inherit;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 10px;
  cursor: pointer;
}

.desktop-icon:hover {
  background: rgba(255, 255, 255, 0.16);
}

.desktop-icon:focus-visible {
  outline: 2px solid #fff;
  outline-offset: -2px;
}

.desktop-icon.selected {
  background: rgba(255, 255, 255, 0.26);
  border-color: rgba(255, 255, 255, 0.45);
}

.icon-glyph {
  font-size: 40px;
  line-height: 1;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.25));
}

.icon-label {
  font-size: 12.5px;
  font-weight: 500;
  color: #fff;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.45);
  padding: 2px 6px;
  border-radius: 6px;
}

/* ---------- Windows ---------- */

#windows {
  position: absolute;
  inset: 0;
  overflow: hidden;
}

.window {
  position: absolute;
  display: flex;
  flex-direction: column;
  min-width: 240px;
  min-height: 150px;
  background: var(--window-bg);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid var(--window-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
}

/* Focused window: stronger shadow + highlighted title bar */
.window.focused {
  box-shadow: var(--shadow-focused);
}

.window.focused .titlebar {
  background: #fff;
  box-shadow: inset 0 -2px 0 var(--accent);
}

/* Title bar: app name + close button, drag handle */
.titlebar {
  height: 40px;
  flex: 0 0 40px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 8px 0 12px;
  background: var(--titlebar-bg);
  touch-action: none;
}

.window.dragging .titlebar {
  cursor: grabbing;
}

.titlebar-icon {
  font-size: 16px;
  line-height: 1;
}

.titlebar-title {
  flex: 1;
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.window:not(.focused) .titlebar-title {
  color: var(--text-soft);
}

.close-btn {
  width: 32px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--text-soft);
  font-size: 14px;
  line-height: 1;
  cursor: pointer;
}

.close-btn:hover {
  background: rgba(208, 62, 62, 0.14);
  color: #c0392b;
}

.close-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

/* Window body — placeholder content until app tickets land */
.window-content {
  flex: 1;
  min-height: 0;
  padding: 20px;
  overflow: auto;
}

.placeholder {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  text-align: center;
  color: var(--text-soft);
  font-size: 13.5px;
}

.placeholder .placeholder-glyph {
  font-size: 48px;
  line-height: 1;
}

/* ---------- Taskbar ---------- */

#taskbar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  height: var(--taskbar-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 10px 0 12px;
  background: rgba(250, 251, 253, 0.62);
  backdrop-filter: blur(18px) saturate(1.4);
  -webkit-backdrop-filter: blur(18px) saturate(1.4);
  border-top: 1px solid rgba(255, 255, 255, 0.5);
  box-shadow: 0 -4px 16px rgba(15, 23, 42, 0.08);
  z-index: 100000;
}

#taskbar-buttons {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  min-width: 0;
  overflow-x: auto;
}

.taskbar-btn {
  display: flex;
  align-items: center;
  gap: 7px;
  max-width: 180px;
  padding: 6px 12px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--text);
  font-family: inherit;
  font-size: 12.5px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
}

.taskbar-btn:hover {
  background: rgba(255, 255, 255, 0.65);
}

.taskbar-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

/* Highlighted state for the focused window's button */
.taskbar-btn.active {
  background: rgba(255, 255, 255, 0.85);
  border-color: rgba(74, 125, 255, 0.4);
  box-shadow: 0 1px 4px rgba(15, 23, 42, 0.12);
}

.taskbar-btn .taskbar-icon {
  font-size: 15px;
  line-height: 1;
}

#clock {
  flex: 0 0 auto;
  min-width: 58px;
  text-align: right;
  font-size: 13px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--text);
}

content.thinking:
Ticket 1 is complete. Next I need to implement Ticket 2: wallpaper.

Requirements:
- 8 built-in presets, implemented purely in CSS: a mix of solid colors, gradients, and simple patterns.
- Right-clicking on an empty area of the desktop opens a context menu containing a "Change wallpaper" item, which leads to a preset picker (a grid of thumbnails).
- The selected wallpaper is persisted to localStorage across reloads.

Design plan:

1. **Presets** (8, CSS-only):
   - `midnight` — solid dark navy (#1b2440 or similar)
   - `mint` — solid pastel green
   - `aurora` — linear gradient (blue/purple/pink)
   - `sunset` — linear gradient (orange/pink)
   - `ocean` — radial or linear gradient (teal/blue)
   - `dunes` — diagonal gradient with soft bands (sand color)
   - `grid` — a solid background + a repeating-linear-gradient grid pattern
   - `dots` — radial-gradient dot pattern

   Implement each preset as a CSS class on `#desktop` (e.g., `wp-midnight`), and each preset class defines `background: ...`.

   Pattern presets:
   - Grid: `background-color: #232a36; background-image: linear-gradient(rgba(255,255,255,.06) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.06) 1px, transparent 1px); background-size: 32px 32px;`
   - Dots: `background-color:#f4f1ea; background-image: radial-gradient(circle at center, rgba(0,0,0,0.12) 2px, transparent 2.5px); background-size: 24px 24px;`
   - Also "stripes": repeating-linear-gradient.

   8 presets:
   1. Aurora — linear-gradient(135deg, #6a8dff, #9b6dff, #ff6ec7) (the current default)
   2. Ocean — linear-gradient(180deg, #0f4c75, #3282b8, #bbe1fa)
   3. Sunset — linear-gradient(135deg, #ff9966, #ff5e62, #7b2ff7)
   4. Forest — linear-gradient(160deg, #134e5e, #71b280)
   5. Midnight — solid #16192b (or a subtle radial)
   6. Cloud — soft light gray/white gradient
   7. Grid — dark grid pattern
   8. Dots — light dot pattern

   Wait, I want a mix: solid colors, gradients, simple patterns. Let me go with 2 solids, 4 gradients, 2 patterns.

2. **Context menu**:
   - On `contextmenu` event on `#desktop`, if the target is the empty desktop area (not on an icon or a window). "Right-clicking on an empty area of the desktop" — that means we should check that the event target is not inside `#windows` (windows are inside the desktop div) and not a desktop icon. Actually icons are buttons, so right-clicking on them probably shouldn't open the OS menu. The spec says "empty area of the desktop". So check: `e.target === desktopEl` or the target is inside `#icons` but not on an icon? More simply: if `e.target.closest(".window")` or `e.target.closest(".desktop-icon")` → suppress default and do nothing. Otherwise, open the custom menu at the cursor position, clamped within the viewport.
   - Menu: a small floating panel with a "Change wallpaper" item (maybe a few other items for looks? The spec only requires a "Change wallpaper" entry. For realism I could add a few more disabled-looking items, but they'd need to do something or be disabled. Keep it simple: just "Change wallpaper" — or add "About"? Better to follow the spec strictly: only the "Change wallpaper" item. I could add a few more functional items but... let me stick to just the one item to avoid scope creep. Actually, having a single-item context menu looks a bit bare, but it matches the spec exactly. Just keep "Change wallpaper".)
   - Clicking "Change wallpaper" closes the context menu and opens the wallpaper picker dialog (a centered window-like modal, not a draggable window — or should it be a real OS window? The spec says "a preset picker (a grid of thumbnails)". I'll make it a modal-style centered panel with a title bar, a grid of 8 thumbnails (each thumbnail renders the same CSS background at small scale), names, a checkmark/highlight on the selected one, and maybe a close button. Clicking a thumbnail sets the wallpaper immediately (with a subtle transition?) and updates persistence. Could also add a "Done"/close button.
   - Clicking elsewhere / Escape closes the context menu.

3. **Persistence**: localStorage key, e.g., `browseros.wallpaper`. On init, read it, validate against the preset list, apply the class. Default when unset: "aurora" (matches the current placeholder gradient).

Implementation details:

- CSS: define `.wallpaper-aurora { background: ... }` etc. on `#desktop`. Replace the hardcoded placeholder background with the default class applied by JS.
- Thumbnails: each thumbnail is a div with a class like `wp-thumb wallpaper-aurora`, sized around 120×75 (16:10). Since the background is a gradient/pattern, it scales fine. For patterns with background-size, the dots/grid will display smaller but still be recognizable. I could override with `background-size` in the thumbnail to keep the pattern legible, but it's fine as is. Actually, for a 120px-wide grid pattern with 32px cells → about 4 columns visible; dots at 24px → a few dots. Legible enough.

- Context menu element: `#context-menu`, hidden by default (`display:none` or a `.hidden` class), positioned absolutely. Items are buttons.

- Picker: `#wallpaper-picker`, centered in the viewport (above the taskbar), a panel with a header "Change wallpaper", a grid of thumbnails (4×2), and a footer with a "Close" button. Clicking a thumbnail applies immediately. Show the current selection (border + check badge).

- z-index: context menu above everything (z-index 200000, above the taskbar's 100000). Picker above windows, below or above the taskbar? Since it's a dialog, put it above windows, maybe z-index 150000. Let me use a `#modal-layer` for the picker.

- Esc key closes the context menu and the picker.

- When a window is focused, clicking the desktop should blur/deselect the window? Not required by the spec; skip.

Also "right-clicking on an empty area of the desktop" — right-clicking on a window should show the default browser context menu (or do nothing). For windows, let the default menu show (don't preventDefault). For icons, also default. For the empty desktop, preventDefault and show the custom menu.

Edge case: the picker itself — should it be draggable? Not required. A centered modal is enough.

Should the picker be an actual window managed by the window manager? Ticket 1's window manager is single-instance per app; the picker isn't an app. Simpler and safer: a modal overlay. The spec doesn't demand it be a window.

Next, on the JS structure:

```js
/* ---------- Wallpaper (ticket 2) ---------- */

const WALLPAPER_KEY = "browseros.wallpaper";
const WALLPAPERS = [
  { id: "aurora", name: "Aurora" },
  ...
];

function currentWallpaper() { ... }
function applyWallpaper(id) { desktopEl.classList.remove(...); desktopEl.classList.add("wallpaper-" + id); }
function saveWallpaper(id) { localStorage.setItem(...) }

// Context menu
function initContextMenu() {
  desktopEl.addEventListener("contextmenu", (e) => {
    if (e.target.closest(".window") || e.target.closest(".desktop-icon")) return; // default browser menu
    e.preventDefault();
    showContextMenu(e.clientX, e.clientY);
  });
  document.addEventListener("click", hideContextMenu);
  window.addEventListener("blur", hideContextMenu);
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") hideContextMenu(); });
  resize also hides
}

function showContextMenu(x, y) { position clamped; display; }
function hideContextMenu() { hide; }

// Picker
function initWallpaperPicker() { build thumbnails from WALLPAPERS; wire clicks; }
function openWallpaperPicker() { ... }
function closeWallpaperPicker() { ... }
```

Init flow: inside `init()`, call `initWallpaper()` which loads the saved wallpaper and sets up the context menu + picker

