/* ============================================================
   Calculator (ticket 3)
   Immediate-execution semantics (Windows standard mode): the
   pending binary operation is evaluated as soon as its right
   operand is complete, so there is no operator precedence.
   ============================================================ */

const CALC_MAX_DIGITS = 16; // display width limit per entry

/** Map a numeric result to a display string (plain, exponential, or Error). */
function calcFormat(n) {
  if (!Number.isFinite(n)) return "Error";
  if (n === 0) return "0"; // normalise -0
  const rounded = Number(n.toPrecision(12)); // drop float noise
  let s = String(rounded);
  if (s.length > CALC_MAX_DIGITS) {
    s = rounded.toExponential(6);
    s = s.replace(/\.?0+e/, "e").replace(/e\+?(-?\d+)$/, "e$1");
  }
  return s;
}

/** Parse a displayed entry back to a number ("" counts as 0). */
function calcParse(text) {
  const n = Number(text);
  return Number.isFinite(n) ? n : 0;
}

/** Apply a pending binary operation; division by zero is an error. */
function calcApply(a, op, b) {
  switch (op) {
    case "+": return a + b;
    case "\u2212": return a - b;
    case "\u00d7": return a * b;
    case "\u00f7":
      if (b === 0) return Infinity; // surfaces as the Error state
      return a / b;
    default: return b;
  }
}

/**
 * Build the calculator UI inside a window's content element and wire up
 * all button and keyboard handling. Returns the display element.
 */
function buildCalculator(root) {
  const calc = document.createElement("div");
  calc.className = "calc";

  const display = document.createElement("div");
  display.className = "calc-display";
  display.textContent = "0";
  display.setAttribute("role", "status");
  display.setAttribute("aria-label", "Calculator display");

  const keys = document.createElement("div");
  keys.className = "calc-keys";
  keys.setAttribute("role", "group");
  keys.setAttribute("aria-label", "Calculator keys");
  // [label, action, css class]
  const KEYS = [
    ["C", "clear", "calc-key-clear"],
    ["\u00b1", "negate", "calc-key-util"],
    ["%", "percent", "calc-key-util"],
    ["\u00f7", "op", "calc-key-util"],
    ["7", "digit"], ["8", "digit"], ["9", "digit"],
    ["\u00d7", "op", "calc-key-util"],
    ["4", "digit"], ["5", "digit"], ["6", "digit"],
    ["\u2212", "op", "calc-key-util"],
    ["1", "digit"], ["2", "digit"], ["3", "digit"],
    ["+", "op", "calc-key-util"],
    ["0", "digit", "calc-key-zero"],
    [".", "decimal"],
    ["=", "equals", "calc-key-equals"],
  ];
  KEYS.forEach(([label, action, extraClass]) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "calc-key" + (extraClass ? " " + extraClass : "");
    btn.dataset.action = action;
    if (label === "0") btn.dataset.label = "0"; // unambiguous target for tests
    btn.textContent = label;
    btn.setAttribute("aria-label", calcKeyAria(label, action));
    btn.addEventListener("click", () => handleKey(label, action));
    keys.append(btn);
  });

  calc.append(display, keys);
  root.append(calc);

  /* ----- Calculator state (immediate-execution model) ----- */

  let acc = 0; // stored left operand
  let pendingOp = null; // "+", "\u2212", "\u00d7", "\u00f7" or null
  let entry = "0"; // the number currently shown, as a string
  let entering = false; // true while the user is typing the right operand
  let startNew = true; // next digit starts a fresh entry
  let lastOp = null; // for repeated "=" presses
  let lastOperand = 0;
  let error = false;

  function countDigits(text) {
    return (text.match(/\d/g) || []).length;
  }

  /** Update the display text and its auto-shrinking font size. */
  function render() {
    display.textContent = entry;
    display.classList.toggle("calc-display-error", error);
    const len = entry.length;
    display.classList.toggle("calc-display-small", len > 10);
    display.classList.toggle("calc-display-tiny", len > 14);
  }

  /** Leave the Error state and return to a clean "0". */
  function clearError() {
    error = false;
    acc = 0;
    pendingOp = null;
    entry = "0";
    entering = false;
    startNew = true;
    lastOp = null;
    lastOperand = 0;
    render();
  }

  function pressDigit(d) {
    if (error) clearError();
    if (startNew) {
      entry = d === "0" ? "0" : d;
      entering = true;
      startNew = false;
    } else if (entry === "0") {
      entry = d; // replace the lone zero
    } else if (entry === "-0") {
      entry = "-" + d;
    } else if (countDigits(entry) < CALC_MAX_DIGITS) {
      entry += d;
    }
    render();
  }

  function pressDecimal() {
    if (error) clearError();
    if (startNew) {
      entry = "0.";
      entering = true;
      startNew = false;
    } else if (!entry.includes(".")) {
      entry += ".";
    }
    render();
  }

  function pressOperator(op) {
    if (error) {
      clearError();
      op = "\u00f7" === op ? op : op; // operators need a left operand; continue from 0
      pendingOp = op;
      acc = 0;
      entry = "0";
      entering = false;
      startNew = true;
      lastOp = null;
      lastOperand = 0;
      render();
      return;
    }
    const current = calcParse(entry);
    if (pendingOp && !startNew) {
      // A complete "acc op entry" pair: evaluate it immediately.
      const result = calcApply(acc, pendingOp, current);
      if (!Number.isFinite(result)) return showError();
      acc = result;
      entry = calcFormat(result);
      entering = false;
    } else {
      // No pending op (or the operator is being replaced): start a pair.
      acc = current;
    }
    pendingOp = op;
    startNew = true;
    lastOp = null;
    lastOperand = 0;
    render();
  }

  function pressEquals() {
    if (error) return; // any input other than clear leaves the error state
    if (pendingOp) {
      const operand = calcParse(entry);
      const result = calcApply(acc, pendingOp, operand);
      lastOp = pendingOp;
      lastOperand = operand;
      pendingOp = null;
      if (!Number.isFinite(result)) return showError();
      acc = result;
      entry = calcFormat(result);
      entering = false;
      startNew = true;
      render();
    } else if (lastOp) {
      // Repeated "=": re-apply the last operation to the current value.
      const result = calcApply(calcParse(entry), lastOp, lastOperand);
      if (!Number.isFinite(result)) return showError();
      acc = result;
      entry = calcFormat(result);
      entering = false;
      startNew = true;
      render();
    }
    // otherwise: nothing to evaluate, leave the display as-is
  }

  function pressPercent() {
    if (error) clearError();
    const value = calcParse(entry);
    let result;
    if (pendingOp === "+" || pendingOp === "\u2212") {
      // "a + b %" means a + (a * b / 100)
      result = (acc * value) / 100;
    } else if (pendingOp === "\u00d7" || pendingOp === "\u00f7") {
      // "a \u00d7 b %" means a \u00d7 (b / 100)
      result = value / 100;
    } else {
      result = 0; // a lone "b %" has nothing to be a percent of
    }
    if (!Number.isFinite(result)) return showError();
    entry = calcFormat(result);
    entering = false;
    startNew = true; // typing a digit now starts a new number
    render();
  }

  function pressNegate() {
    if (error) return;
    if (entry === "0" || entry === "0." || entry === "-0") return;
    if (entry.startsWith("-")) entry = entry.slice(1);
    else entry = "-" + entry;
    render();
  }

  function pressClear() {
    clearError(); // also covers the normal reset to zero
  }

  function pressBackspace() {
    if (error) {
      clearError();
      return;
    }
    if (startNew || !entering) return; // results cannot be edited
    if (entry.length > 1) entry = entry.slice(0, -1);
    else entry = "0";
    if (entry === "-0") entry = "0";
    render();
  }

  /** Enter the "Error" state (divide by zero). */
  function showError() {
    error = true;
    acc = 0;
    pendingOp = null;
    entry = "Error";
    entering = false;
    startNew = true;
    lastOp = null;
    lastOperand = 0;
    render();
  }

  /** Dispatch a key press by its button action (used by clicks and the keyboard). */
  function handleKey(label, action) {
    switch (action) {
      case "digit": pressDigit(label); break;
      case "decimal": pressDecimal(); break;
      case "op": pressOperator(label); break;
      case "equals": pressEquals(); break;
      case "percent": pressPercent(); break;
      case "negate": pressNegate(); break;
      case "clear": pressClear(); break;
    }
  }

  /** Keyboard handler: only active while the calculator window is focused. */
  function onKeyDown(e) {
    const win = calc.closest(".window");
    if (!win || !win.classList.contains("focused")) return;
    const t = e.target;
    if (t && t.closest && t.closest("input, textarea, select")) return;
    let action = null;
    let label = null;
    if (/^[0-9]$/.test(e.key)) {
      action = "digit";
      label = e.key;
    } else if (e.key === "." || e.key === ",") {
      action = "decimal";
    } else if (e.key === "+") {
      action = "op"; label = "+";
    } else if (e.key === "-") {
      action = "op"; label = "\u2212";
    } else if (e.key === "*" || e.key === "x" || e.key === "X") {
      action = "op"; label = "\u00d7";
    } else if (e.key === "/") {
      action = "op"; label = "\u00f7"; e.preventDefault(); // avoid the quick-find bar
    } else if (e.key === "%") {
      action = "percent";
    } else if (e.key === "Enter" || e.key === "=') {
      action = "equals";
    } else if (e.key === "Escape") {
      action = "clear";
    } else if (e.key === "Backspace") {
      pressBackspace();
      return;
    } else {
      return;
    }
    if (t && t.closest && t.closest(".calc-key")) return; // native click already handled it
    e.preventDefault();
    handleKey(label, action);
    flashKey(label, action);
  }

  /** Briefly highlight the key that a keyboard press maps to. */
  function flashKey(label, action) {
    let btn;
    if (label !== null && label !== undefined) {
      btn = keys.querySelector('.calc-key[data-label="' + label + '"]') ||
            keys.querySelector(".calc-key");
      btn = [...keys.querySelectorAll(".calc-key")].find((b) => b.textContent === label) || null;
    }
    if (!btn && action) {
      btn = keys.querySelector('.calc-key[data-action="' + action + '"]');
    }
    if (!btn) return;
    btn.classList.add("pressed");
    setTimeout(() => btn.classList.remove("pressed"), 120);
  }

  document.addEventListener("keydown", onKeyDown);
  render();
  return display;
}

/** Human-readable name for a key, used as its aria-label. */
function calcKeyAria(label, action) {
  if (action === "digit") return "Digit " + label;
  switch (label) {
    case "C": return "Clear";
    case "\u00b1": return "Toggle sign";
    case "%": return "Percent";
    case "\u00f7": return "Divide";
    case "\u00d7": return "Multiply";
    case "\u2212": return "Subtract";
    case "+": return "Add";
    case ".": return "Decimal point";
    case "=": return "Equals";
    default: return label;
  }
}

/** Content builder used by createWindow; placeholder until the app's ticket lands. */
function buildAppContent(appId, app) {
  if (appId === "calculator") return buildCalculator(document.createDocumentFragment ? null : null);
  return placeholderContent(app);
}

/* ---------- Startup ---------- */

  // Keep windows fully inside the desktop when the viewport resizes:
  // shrink oversized windows and re-clamp their positions.
  window.addEventListener("resize", () => {
    const { width, height } = desktopBounds();
    windows.forEach((win) => {
      const w = Math.min(win.offsetWidth, Math.max(width - 8, 240));
      const h = Math.min(win.offsetHeight, Math.max(height - 8, 150));
      win.style.width = w + "px";
      win.style.height = h + "px";
      const x = Number.parseFloat(win.style.left) || 0;
      const y = Number.parseFloat(win.style.top) || 0;
      setPosition(win, x, y);
    });
  });

  // Keyboard support for apps whose window is focused (ticket 3: calculator).
  window.addEventListener("keydown", (e) => {
    windows.forEach((win) => {
      if (!win.classList.contains("focused")) return;
      const app = win.dataset.app;
      if (app === "calculator") appKeyHandlers.calculator(e);
    });
  });
}

