  /* ----- Calculator state (immediate-execution model) ----- */

  let acc = 0; // stored left operand
  let pendingOp = null; // "+", "\u2212", "\u00d7", "\u00f7" or null
  let entry = "0"; // the number currently shown, as a string
  let entering = false; // true while the user is typing the right operand
  let startNew = true; // next digit starts a fresh entry
  let lastOp = null; // for repeated "=" presses
  let lastOperand = 0;
  let error = false;

  function countDigits(text) {
    return (text.match(/\d/g) || []).length;
  }

  /** Update the display text and its auto-shrinking font size. */
  function render() {
    display.textContent = entry;
    display.classList.toggle("calc-display-error", error);
    const len = entry.length;
    display.classList.toggle("calc-display-small", len > 10);
    display.classList.toggle("calc-display-tiny", len > 14);
  }

  /** Leave the Error state and return to a clean "0". */
  function clearError() {
    error = false;
    acc = 0;
    pendingOp = null;
    entry = "0";
    entering = false;
    startNew = true;
    lastOp = null;
    lastOperand = 0;
    render();
  }

  function pressDigit(d) {
    if (error) clearError();
    if (startNew) {
      entry = d === "0" ? "0" : d;
      entering = true;
      startNew = false;
    } else if (entry === "0") {
      entry = d; // replace the lone zero
    } else if (entry === "-0") {
      entry = "-" + d;
    } else if (countDigits(entry) < CALC_MAX_DIGITS) {
      entry += d;
    }
    render();
  }

  function pressDecimal() {
    if (error) clearError();
    if (startNew) {
      entry = "0.";
      entering = true;
      startNew = false;
    } else if (!entry.includes(".")) {
      entry += ".";
    }
    render();
  }

  function pressOperator(op) {
    if (error) {
      clearError();
      op = "\u00f7" === op ? op : op; // operators need a left operand; continue from 0
      pendingOp = op;
      acc = 0;
      entry = "0";
      entering = false;
      startNew = true;
      lastOp = null;
      lastOperand = 0;
      render();
      return;
    }
    const current = calcParse(entry);
    if (pendingOp && !startNew) {
      // A complete "acc op entry" pair: evaluate it immediately.
      const result = calcApply(acc, pendingOp, current);
      if (!Number.isFinite(result)) return showError();
      acc = result;
      entry = calcFormat(result);
      entering = false;
    } else {
      // No pending op (or the operator is being replaced): start a pair.
      acc = current;
    }
    pendingOp = op;
    startNew = true;
    lastOp = null;
    lastOperand = 0;
    render();
  }

  function pressEquals() {
    if (error) return; // any input other than clear leaves the error state
    if (pendingOp) {
      const operand = calcParse(entry);
      const result = calcApply(acc, pendingOp, operand);
      lastOp = pendingOp;
      lastOperand = operand;
      pendingOp = null;
      if (!Number.isFinite(result)) return showError();
      acc = result;
      entry = calcFormat(result);
      entering = false;
      startNew = true;
      render();
    } else if (lastOp) {
      // Repeated "=": re-apply the last operation to the current value.
      const result = calcApply(calcParse(entry), lastOp, lastOperand);
      if (!Number.isFinite(result)) return showError();
      acc = result;
      entry = calcFormat(result);
      entering = false;
      startNew = true;
      render();
    }
    // otherwise: nothing to evaluate, leave the display as-is
  }

  function pressPercent() {
    if (error) clearError();
    const value = calcParse(entry);
    let result;
    if (pendingOp === "+" || pendingOp === "\u2212") {
      // "a + b %" means a + (a * b / 100)
      result = (acc * value) / 100;
    } else if (pendingOp === "\u00d7" || pendingOp === "\u00f7") {
      // "a \u00d7 b %" means a \u00d7 (b / 100)
      result = value / 100;
    } else {
      result = 0; // a lone "b %" has nothing to be a percent of
    }
    if (!Number.isFinite(result)) return showError();
    entry = calcFormat(result);
    entering = false;
    startNew = true; // typing a digit now starts a new number
    render();
  }

  function pressNegate() {
    if (error) return;
    if (entry === "0" || entry === "0." || entry === "-0") return;
    if (entry.startsWith("-")) entry = entry.slice(1);
    else entry = "-" + entry;
    render();
  }

  function pressClear() {
    clearError(); // also covers the normal reset to zero
  }

  function pressBackspace() {
    if (error) {
      clearError();
      return;
    }
    if (startNew || !entering) return; // results cannot be edited
    if (entry.length > 1) entry = entry.slice(0, -1);
    else entry = "0";
    if (entry === "-0") entry = "0";
    render();
  }

  /** Enter the "Error" state (divide by zero). */
  function showError() {
    error = true;
    acc = 0;
    pendingOp = null;
    entry = "Error";
    entering = false;
    startNew = true;
    lastOp = null;
    lastOperand = 0;
    render();
  }

  /** Dispatch a key press by its button action (used by clicks and the keyboard). */
  function handleKey(label, action) {
    switch (action) {
      case "digit": pressDigit(label); break;
      case "decimal": pressDecimal(); break;
      case "op": pressOperator(label); break;
      case "equals": pressEquals(); break;
      case "percent": pressPercent(); break;
      case "negate": pressNegate(); break;
      case "clear": pressClear(); break;
    }
  }

  /** Keyboard handler: only active while the calculator window is focused. */
  function onKeyDown(e) {
    const win = calc.closest(".window");
    if (!win || !win.classList.contains("focused")) return;
    const t = e.target;
    if (t && t.closest && t.closest("input, textarea, select")) return;
    let action = null;
    let label = null;
    if (/^[0-9]$/.test(e.key)) {
      action = "digit";
      label = e.key;
    } else if (e.key === "." || e.key === ",") {
      action = "decimal";
    } else if (e.key === "+") {
      action = "op"; label = "+";
    } else if (e.key === "-") {
      action = "op"; label = "\u2212";
    } else if (e.key === "*" || e.key === "x" || e.key === "X") {
      action = "op"; label = "\u00d7";
    } else if (e.key === "/") {
      action = "op"; label = "\u00f7"; e.preventDefault(); // avoid the quick-find bar
    } else if (e.key === "%") {
      action = "percent";
    } else if (e.key === "Enter" || e.key === "=') {
      action = "equals";
    } else if (e.key === "Escape") {
      action = "clear";
    } else if (e.key === "Backspace") {
      pressBackspace();
      return;
    } else {
      return;
    }
    if (t && t.closest && t.closest(".calc-key")) return; // native click already handled it
    e.preventDefault();
    handleKey(label, action);
    flashKey(label, action);
  }

  /** Briefly highlight the key that a keyboard press maps to. */
  function flashKey(label, action) {
    let btn;
    if (label !== null && label !== undefined) {
      btn = keys.querySelector('.calc-key[data-label="' + label + '"]') ||
