      btn = keys.querySelector('.calc-key[data-action="' + action + '"]');
    }
    if (!btn) return;
    btn.classList.add("pressed");
    setTimeout(() => btn.classList.remove("pressed"), 120);
  }

  document.addEventListener("keydown", onKeyDown);
  render();
  return display;
}

