const CALC_MAX_DIGITS = 16; // display width limit per entry

/** Map a numeric result to a display string (plain, exponential, or Error). */
function calcFormat(n) {
  if (!Number.isFinite(n)) return "Error";
  if (n === 0) return "0"; // normalise -0
  const rounded = Number(n.toPrecision(12)); // drop float noise
  let s = String(rounded);
  if (s.length > CALC_MAX_DIGITS) {
    s = rounded.toExponential(6);
    s = s.replace(/\.?0+e/, "e").replace(/e\+?(-?\d+)$/, "e$1");
  }
  return s;
