cd /private/var/folders/b2/9__21c7903l0ymk4tnddnc_r0000gn/T/llm-interview-runs/pi-run-1786892583579-rxx88f/work && cat >> style.css <<'EOF'

/* ---------- Calculator (ticket 3) ---------- */

.calc {
  height: 100%;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 2px 4px 6px;
}

.calc-display {
  flex: 0 0 auto;
  min-height: 54px;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  padding: 8px 14px;
  font-size: 30px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.5px;
  line-height: 1.15;
  color: var(--text);
  background: rgba(255, 255, 255, 0.65);
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 10px;
  overflow: hidden;
  white-space: nowrap;
  user-select: none;
}

/* Longer numbers step down so they stay readable */
.calc-display-small {
  font-size: 22px;
}

.calc-display-tiny {
  font-size: 16px;
}

.calc-display-error {
  color: #c0392b;
}

.calc-keys {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-rows: 1fr;
  gap: 7px;
}

.calc-key {
  border: none;
  border-radius: 9px;
  background: #fff;
  color: var(--text);
  font-family: inherit;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.1);
  transition: background 0.12s ease, transform 0.05s ease;
}

.calc-key:hover {
  background: #f2f5fa;
}

.calc-key:active,
.calc-key.pressed {
  background: #e4eaf4;
  transform: scale(0.97);
}

.calc-key:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

/* Utility column: sign, percent, operators */
.calc-key-util {
  background: #eef1f7;
  font-size: 16px;
  color: var(--text);
}

.calc-key-util:hover {
  background: #e2e8f2;
}

/* Clear key: subtle warning tint */
.calc-key-clear {
  background: #fdeeee;
  color: #c0392b;
  font-weight: 600;
}

.calc-key-clear:hover {
  background: #f8dcdc;
}

/* Equals key: accent */
.calc-key-equals {
  background: var(--accent);
  color: #fff;
  font-weight: 600;
}

.calc-key-equals:hover {
  background: #3d6cf0;
}

/* Zero key spans the two cells left of "decimal" */
.calc-key-zero {
  grid-column: span 2;
}
EOF
