  if (s.length > CALC_MAX_DIGITS) {
    if (Math.abs(rounded) < 1) {
      // Small decimals: the "0." prefix costs width, so trim digits to fit.
      s = rounded.toPrecision(CALC_MAX_DIGITS - 2)
