    lastOperand = operand;
    pendingOp = null;
    acc = result;
    entry = calcFormat(result);
    entering = false;
    startNew = true;
    render();
  }

  function pressPercent() {
    if (error) clearAll();
    const value = calcParse(entry);
    let result;
    if (pendingOp === "+" || pendingOp === "\u2212") {
